function [coef,e,F0,meanErms]=Polyfit3D(X,Y,cc,degree)
%%
% X: Matrix
% Y: 
% cc: punto de grafica para verificación de regresión en la dimensión 3, if
% cc = [] no se genera grafica de la regresión
% degree: grado de la regresión en la tercera dimensión
% 0: Y = coef1*X (Relación proporcional)
% 1: Y = coef2*X+coef1 (Ecuación lineal)
% 2 - 7 (Polinomios de 2do a 7mo orden)

for i = 1:numel(degree)
    
    switch(degree(i))
        case 0
            [coefaux,eaux,F0aux]=Polyfit01_3D(X,Y,cc);
        case 1
            [coefaux,eaux,F0aux]=Polyfit1_3D(X,Y,cc);
        case 2
            [coefaux,eaux,F0aux]=Polyfit2_3D(X,Y,cc);
        case 3
            [coefaux,eaux,F0aux]=Polyfit3_3D(X,Y,cc);
        case 4
            [coefaux,eaux,F0aux]=Polyfit4_3D(X,Y,cc);
        case 5
            [coefaux,eaux,F0aux]=Polyfit5_3D(X,Y,cc);
        case 6
            [coefaux,eaux,F0aux]=Polyfit6_3D(X,Y,cc);
        case 7
            [coefaux,eaux,F0aux]=Polyfit7_3D(X,Y,cc);

        otherwise
            disp("Polinomio no implementado")
    end

    if(numel(degree)>1)
        coef{i} = coefaux;
        e{i} = eaux;
        F0{i} = F0aux;
    else
        coef = coefaux;
        e = eaux;
        F0 = F0aux;
    end

    meanErms(i,1) = mean(eaux(:),'omitnan'); 
    meanErms(i,2) = max(eaux(:)); 
end

end



function [coef,e,F0] = Polyfit01_3D(Xi,Yi,cc)

% X = Xi([300 500],500,:);
% Y = Yi([300 500],500,:);

% Xi = double(X);
% mX =mean(Xi,3,'omitnan');
% sX =std(Xi,[],3,'omitnan');
% X = (Xi - mX)./sX;
% X = Xi; Y = Yi;
% 
% % Yi = Y;
% % mY = repmat(mean(Yi,3,'omitnan'),[1 1 size(Yi,3)]);
% % sY = repmat(std(Yi,[],3,'omitnan'),[1 1 size(Yi,3)]);
% % Y = (Yi - mY)./sY;
% Y = Yi;
% 
% n=1;
% X2=1;
% tic
F0  = sum(~isnan(Xi),3); 
% 
%             F0  = sum(~isnan(X),3);    Z0 = sum(Y+(Xi*0),3,'omitnan');     disp('..')
% X2 = X;     F1  = sum(X2,3,'omitnan'); Z1 = sum(Y.*X2,3,'omitnan'); disp('..')
% X2 = X2.*X; F2  = sum(X2,3,'omitnan'); 
% 
% 
% dete = (F1.*F1 - F0.*F2);
% a= -(F0.*Z1 - F1.*Z0)./dete;
% b= (F1.*Z1 - F2.*Z0)./dete;
% 
% 
% 
% b =( b - (a.*mX)./sX);
a = sum(Yi.*Xi,3,'omitnan')./sum(Xi.*Xi,3,'omitnan');


% X = Xi;
if(~isempty(cc))
    ci = cc(1); cj = cc(2);
    x = shiftdim(Xi(ci,cj,:));
    y = shiftdim(Yi(ci,cj,:));
    figure, plot(x,y,'*')
    hold on, plot(x,a(ci,cj)*x)
    % xc = (x-mean(x))/std(x);
end
% yc = polyval(polyfit(x,y,5),x);
% ncoef3x = cat(3,A3,A2,A1,A0);


coef = cat(3,a,a*0);

% XX = zeros(size(X));
% n=size(coef,3);


ex = Yi-a.*Xi;
e = sqrt(sum((ex).^2,3,'omitnan')./F0);



end


function [coef,e,F0] = Polyfit1_3D(Xi,Yi,cc)

% X = Xi([300 500],500,:);
% Y = Yi([300 500],500,:);

% Xi = double(X);
mX =mean(Xi,3,'omitnan');
sX =std(Xi,[],3,'omitnan');
X = (Xi - mX)./sX;

% Yi = Y;
% mY = repmat(mean(Yi,3,'omitnan'),[1 1 size(Yi,3)]);
% sY = repmat(std(Yi,[],3,'omitnan'),[1 1 size(Yi,3)]);
% Y = (Yi - mY)./sY;
Y = Yi;

n=1;
X2=1;
tic

            F0  = sum(~isnan(X),3);    Z0 = sum(Y+(Xi*0),3,'omitnan');     disp('..')
X2 = X;     F1  = sum(X2,3,'omitnan'); Z1 = sum(Y.*X2,3,'omitnan'); disp('..')
X2 = X2.*X; F2  = sum(X2,3,'omitnan'); 


dete = (F1.*F1 - F0.*F2);
a= -(F0.*Z1 - F1.*Z0)./dete;
b= (F1.*Z1 - F2.*Z0)./dete;



b =( b - (a.*mX)./sX);
a =( a./(sX));


% X = Xi;
if(~isempty(cc))
    ci = cc(1); cj = cc(2);
    x = shiftdim(Xi(ci,cj,:));
    y = shiftdim(Yi(ci,cj,:));
    figure, plot(x,y,'*')
    hold on, plot(x,a(ci,cj)*x+b(ci,cj))
    % xc = (x-mean(x))/std(x);
end
% yc = polyval(polyfit(x,y,5),x);
% ncoef3x = cat(3,A3,A2,A1,A0);


coef = cat(3,a,b);

% XX = zeros(size(X));
% n=size(coef,3);

X2=1; XX =repmat(coef(:,:,2),[1,1,size(Xi,3)]);
for j=1:n  
  X2 = X2.*Xi;
  XX = XX+repmat(coef(:,:,n+1-j),[1,1,size(Xi,3)]).*X2;  
end

ex = Yi-XX;
e = sqrt(sum((ex).^2,3,'omitnan')./F0);



end

function [coef,e,N]  = Polyfit2_3D(X,Y,cc)

% Xn = X;
% Xn(~isnan(X)) = 0;
% X(isnan(X)) = 1;




F1=sum(X,3,'omitnan');
F2=sum(X.*X,3,'omitnan');
F3=sum(X.*X.*X,3,'omitnan');
F4=sum(X.*X.*X.*X,3,'omitnan');
N=sum(~isnan(X),3); 
% N=size(X,3);



dete = -F4.*F1.*F1+2.*F1.*F2.*F3-F2.*F2.*F2+N.*F4.*F2-N.*F3.*F3;

Z2 = sum(Y.*X.*X,3,'omitnan');
Z1 = sum(Y.*X,3,'omitnan');
Z0 = sum(Y+(X*0),3,'omitnan');

% aa = ;
a= (- Z2.*F1.*F1 + Z1.*F1.*F2 + F3.*Z0.*F1 - Z0.*F2.*F2 + N.*Z2.*F2 - N.*F3.*Z1)./(dete+eps); 

b = (F1.*F2.*Z2 - F2.*F2.*Z1 - F1.*F4.*Z0 + F2.*F3.*Z0 - N.*F3.*Z2 + N.*F4.*Z1)./(dete+eps); 

c = (Z0 - a.*F2 - b.*F1)./N;

coef = cat(3,a,b,c);


% figure, plot(shiftdim(X(cj,ci,:)),shiftdim(Y(cj,ci,:)),'*')
% hold on, plot(shiftdim(X(cj,ci,:)),shiftdim(X(cj,ci,:)).*shiftdim(X(cj,ci,:))*a(cj,ci)+shiftdim(X(cj,ci,:))*b(cj,ci)+c(cj,ci))

if(~isempty(cc))
    cx = cc(1); cy = cc(2);
    x = shiftdim(X(cx,cy,:));
    y = shiftdim(Y(cx,cy,:));
    figure, plot(x,y,'*')
    x = sort(x);
    hold on, plot(x,a(cx,cy)*x.^2+b(cx,cy)*x+c(cx,cy));
end



%XX = zeros(size(X));
%n=size(coef,3);
%for j=1:n
 XX = repmat(coef(:,:,1),[1,1,size(X,3)]).*X.*X+ repmat(coef(:,:,2),[1,1,size(X,3)]).*X+ repmat(coef(:,:,3),[1,1,size(X,3)]);  
%end
ex = Y-XX;

e = sqrt(sum((ex).^2,3,'omitnan')./N);


end

function [coef,e,F0] = Polyfit3_3D(X,Y,cc)
% X = X([300 500],500,:);
% Y = Y([300 500],500,:);
Xi = X;
mX = mean(X,3,'omitnan');
sX = std(X,[],3,'omitnan');
X = (X - mX)./sX;


F0  = sum(~isnan(X),3);    Z0 = sum(Y.*(X*0+1),3,'omitnan');     disp('..')
X2 = X;     F1  = sum(X2,3,'omitnan'); Z1 = sum(Y.*X2,3,'omitnan'); disp('..')
X2 = X2.*X; F2  = sum(X2,3,'omitnan'); Z2 = sum(Y.*X2,3,'omitnan'); disp('..')
X2 = X2.*X; F3  = sum(X2,3,'omitnan'); Z3 = sum(Y.*X2,3,'omitnan'); disp('..')
X2 = X2.*X; F4  = sum(X2,3,'omitnan');
X2 = X2.*X; F5  = sum(X2,3,'omitnan');
X2 = X2.*X; F6  = sum(X2,3,'omitnan'); disp('..')


tic

F1_2 = F1.*F1;
F2_2 = F2.*F2;
F3_2 = F3.*F3;
F4_2 = F4.*F4;
F5_2 = F5.*F5;
F1_F2 = F1.*F2;
F1_F2_F3 = F1_F2.*F3;
F2_F3 = F2.*F3;


dete = ((F6.*F1_2.*F4 - F1_2.*F5_2 - 2*F6.*F1_F2_F3 + 2*F1_F2.*F4.*F5 +2*F1.*F3_2.*F5 -2*F1.*F3.*F4_2 + F6.*F2_2.*F2 -2*F2_2.*F3.*F5 - F2_2.*F4_2 + 3.*F2.*F3_2.*F4 - F0.*F6.*F2.*F4 + F0.*F2.*F5_2 - F3_2.*F3_2 + F0.*F6.*F3_2 -2*F0.*F3.*F4.*F5 + F0.*F4_2.*F4)+eps);
a=-(- Z3.*F1_2.*F4 + F5.*Z2.*F1_2 + 2*Z3.*F1_F2_F3 - Z2.*F1_F2.*F4 - F5.*Z1.*F1_F2 - Z2.*F1.*F3_2 + Z1.*F1.*F3.*F4 - F5.*Z0.*F1.*F3 + Z0.*F1.*F4_2 - Z3.*F2_2.*F2 + Z2.*F2_2.*F3 + Z1.*F2_2.*F4 + F5.*Z0.*F2_2- Z1.*F2.*F3_2 - 2*Z0.*F2_F3.*F4 + F0.*Z3.*F2.*F4 - F0.*F5.*Z2.*F2 + Z0.*F3_2.*F3 - F0.*Z3.*F3_2 + F0.*Z2.*F3.*F4 + F0.*F5.*Z1.*F3 - F0.*Z1.*F4_2)./dete;
b= (F0.*F4_2.*Z2 - F3_2.*F3.*Z1 - F2.*F4_2.*Z0 + F1.*F3_2.*Z3 + F2.*F3_2.*Z2 + F3_2.*F4.*Z0 - F2_2.*F3.*Z3 + F2_2.*F6.*Z0 - F1_2.*F5.*Z3 + F1_2.*F6.*Z2 + F0.*F2.*F5.*Z3 - F0.*F2.*F6.*Z2 - F0.*F3.*F4.*Z3 + F0.*F3.*F6.*Z1 - F0.*F4.*F5.*Z1 + F1_F2.*F4.*Z3 - F1_F2.*F6.*Z1 -2*F1.*F3.*F4.*Z2 + F1.*F3.*F5.*Z1 - F1.*F3.*F6.*Z0 + F1.*F4.*F5.*Z0 + F2_F3.*F4.*Z1 - F2_F3.*F5.*Z0)./dete;
c= (F0.*F5_2.*Z1 - F3_2.*F3.*Z2 - F1.*F5_2.*Z0 + F0.*F4_2.*Z3 - F3.*F4_2.*Z0 + F2.*F3_2.*Z3 + F3_2.*F4.*Z1 + F3_2.*F5.*Z0 - F2_2.*F4.*Z3 + F2_2.*F6.*Z1 - F0.*F3.*F5.*Z3 + F0.*F3.*F6.*Z2 - F0.*F4.*F5.*Z2 - F0.*F4.*F6.*Z1 + F1_F2.*F5.*Z3 - F1_F2.*F6.*Z2 - F1.*F3.*F4.*Z3 + F1.*F3.*F5.*Z2 + F1.*F4.*F6.*Z0 + F2_F3.*F4.*Z2 -2*F2_F3.*F5.*Z1 - F2_F3.*F6.*Z0 + F2.*F4.*F5.*Z0)./dete;

% d= (- Z3.*F2_2.*F5 + F6.*Z2.*F2_2+ 2*Z3.*F2_F3.*F4 - Z2.*F2_F3.*F5 - F6.*Z1.*F2_F3 - Z2.*F2.*F4_2 + Z1.*F2.*F4.*F5 - F6.*Z0.*F2.*F4 + Z0.*F2.*F5_2 - Z3.*F3_2.*F3 + Z2.*F3_2.*F4 + Z1.*F3_2.*F5 + F6.*Z0.*F3_2 - Z1.*F3.*F4_2 -2*Z0.*F3.*F4.*F5 + F1.*Z3.*F3.*F5 - F1.*F6.*Z2.*F3 + Z0.*F4_2.*F4 - F1.*Z3.*F4_2 + F1.*Z2.*F4.*F5 + F1.*F6.*Z1.*F4 - F1.*Z1.*F5_2)./dete;
d = sum((Y-a.*X.*X.*X-b.*X.*X-c.*X),3,'omitnan')./F0;
toc

d =d - (c.*mX(:,:,1))./sX(:,:,1) + (b.*mX(:,:,1).^2)./sX(:,:,1).^2 - (a.*mX(:,:,1).^3)./sX(:,:,1).^3;
c =c./sX(:,:,1) - (2.*b.*mX(:,:,1))./sX(:,:,1).^2 + (3.*a.*mX(:,:,1).^2)./sX(:,:,1).^3;
b =b./sX(:,:,1).^2 - (3.*a.*mX(:,:,1))./sX(:,:,1).^3;
a = a./sX(:,:,1).^3;

X =Xi;


if(~isempty(cc))
    cx = cc(1); cy = cc(2);
    x = shiftdim(X(cx,cy,:));
    y = shiftdim(Y(cx,cy,:));
    figure, plot(x,y,'*')
    x = sort(x);
    hold on, plot(x,a(cx,cy)*x.^3+b(cx,cy)*x.^2+c(cx,cy)*x.^1+d(cx,cy)*x.^0);%+e(500,500)*x+f(500,500))
end

coef = cat(3,a,b,c,d);

XX = coef(:,:,1).*X.*X.*X + coef(:,:,2).*X.*X+ coef(:,:,3).*X + coef(:,:,4);

ex = Y-XX;
e = sqrt(sum((ex).^2,3,'omitnan')./F0);


end

function [coef,e,F0] = Polyfit4_3D(Xi,Y,cc)

mX = repmat(mean(Xi,3,'omitnan'),[1 1 size(Xi,3)]);
sX = repmat(std(Xi,[],3,'omitnan'),[1 1 size(Xi,3)]);
X = (Xi - mX)./sX;


n=4;
% X2=1;
tic

            F0  = sum(~isnan(X),3);    Z0 = sum(Y+(0*Xi),3,'omitnan');     disp('..')
X2 = X;     F1  = sum(X2,3,'omitnan'); Z1 = sum(Y.*X2,3,'omitnan'); disp('..')
X2 = X2.*X; F2  = sum(X2,3,'omitnan'); Z2 = sum(Y.*X2,3,'omitnan'); disp('..')
X2 = X2.*X; F3  = sum(X2,3,'omitnan'); Z3 = sum(Y.*X2,3,'omitnan'); disp('..')
X2 = X2.*X; F4  = sum(X2,3,'omitnan'); Z4 = sum(Y.*X2,3,'omitnan'); disp('..')
X2 = X2.*X; F5  = sum(X2,3,'omitnan');
X2 = X2.*X; F6  = sum(X2,3,'omitnan'); disp('..')
X2 = X2.*X; F7  = sum(X2,3,'omitnan'); disp('..')
X2 = X2.*X; F8  = sum(X2,3,'omitnan'); disp('..')

toc

